package dev.hoi.client.map;

import com.google.gson.Gson;
import dev.hoi.client.ClientCampaignHud;
import dev.hoi.protocol.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.Consumer;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;

public final class MapMissionOverlayRenderTest {
    record Fixture(String mode,String country,List<String> selected,List<ProtocolAtlasScene.Box> active,List<ProtocolAtlasScene.Box> cancelled,List<ProtocolCommanderHud.MovementQuad> movement,List<ProtocolCommanderHud.MovementQuad> progressed,String clearAction,List<Step> sequence) {}
    record Step(long gameMinute,double progress,String province,ProtocolUnitHud.Counter counter,List<ProtocolCommanderHud.MovementQuad> movement) {}
    record SequenceEvidence(String stage,long gameMinute,double progress,String province,double x,double z,int screenX,int screenY,String image) {}
    record Evidence(String mode,int width,int height,int guiScale,String fixtureSha256,int boxes,int activeArrowPixels,int removedArrowPixels,String activeImage,String progressedImage,String cancelledImage,String clearAction) {}
    private MapMissionOverlayRenderTest() {}
    public static void run(ClientGameTestContext context,Consumer<String> command) {
        String directory=System.getenv("HOI_MISSION_OVERLAY_FIXTURES");if(directory==null||directory.isBlank())return;
        var evidence=new ArrayList<Evidence>();var original=context.computeOnClient(client->new Object[]{client.options.guiScale().get(),client.gui.hud.isHidden(),ClientCampaignHud.country().isEmpty()?ProtocolHudPayloads.State.HIDDEN:ProtocolHudPayloads.State.of(ClientCampaignHud.country(),ClientCampaignHud.hud())});
        try {
            context.setScreen(()->null);context.runOnClient(client->{if(!client.gui.hud.isHidden())client.gui.hud.toggle();client.options.fov().set(60);});
            for(String mode:List.of("ARMY","AIR","NAVY")){
                byte[] bytes=Files.readAllBytes(Path.of(directory,mode.toLowerCase(Locale.ROOT)+".json"));var fixture=new Gson().fromJson(new String(bytes,java.nio.charset.StandardCharsets.UTF_8),Fixture.class);String hash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));
                if(!mode.equals(fixture.mode())||!"KOR".equals(fixture.country())||fixture.selected().isEmpty()||fixture.active().isEmpty()&&fixture.movement().isEmpty()||!fixture.cancelled().isEmpty()||fixture.clearAction()==null||fixture.clearAction().isBlank()||fixture.active().stream().anyMatch(b->b.material()!=ProtocolAtlasScene.Material.DEPLOYMENT&&b.material()!=ProtocolAtlasScene.Material.AIR_SELECTED))throw new AssertionError("Actual source command and cancellation fixture required: "+mode);
                var mesh=MapSceneMesh.build("minecraft:overworld",fixture.active(),fixture.movement());double minX=Double.POSITIVE_INFINITY,minZ=Double.POSITIVE_INFINITY,maxX=Double.NEGATIVE_INFINITY,maxZ=Double.NEGATIVE_INFINITY;
                for(var tile:mesh.tiles()){var vertices=tile.vertices();for(int i=0;i<vertices.length;i+=8){minX=Math.min(minX,vertices[i]);maxX=Math.max(maxX,vertices[i]);minZ=Math.min(minZ,vertices[i+2]);maxZ=Math.max(maxZ,vertices[i+2]);}}
                double offsetX=4-minX,offsetZ=4-minZ,width=maxX-minX,depth=maxZ-minZ,span=Math.max(width,depth)+8;if(span>64)throw new AssertionError("Choose a local actual source order for unscaled renderer evidence: "+mode+" span="+span);
                var local=fixture.active().stream().map(b->new ProtocolAtlasScene.Box((float)(b.x()+offsetX),b.y()+186,(float)(b.z()+offsetZ),b.sx(),b.sy(),b.sz(),b.yaw(),b.material())).toList();var movement=translate(fixture.movement(),offsetX,offsetZ);var progressed=translate(fixture.progressed(),offsetX,offsetZ);int extent=(int)Math.ceil(span);command.accept("fill 0 249 0 "+extent+" 249 "+extent+" minecraft:stone strict");command.accept("tp @a "+(width/2+4)+" "+(250+Math.max(20,span*.95))+" "+(depth/2+4)+" 0 90");
                for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
                    context.getInput().resizeWindow(size[0],size[1]);context.runOnClient(client->{client.options.guiScale().set(2);MapSceneRenderer.clear();ClientCampaignHud.accept(ProtocolHudPayloads.State.of(fixture.country(),ProtocolCountryHud.UNKNOWN));receive(fixture.country(),local,movement);});context.waitFor(client->MapSceneRenderer.visibleTileCount()>0);context.waitTicks(5);context.runOnClient(client->{if(Math.abs(client.getWindow().getGuiScale()-2)>.0001)throw new AssertionError("GUI2 render evidence requires actual GUI scale 2");});
                    String suffix=mode.toLowerCase(Locale.ROOT)+"-"+size[0]+"x"+size[1]+"-gui2";Path active=context.takeScreenshot("hoi-mission-overlay-source-active-"+suffix);
                    Path progressImage=null;if(!progressed.isEmpty()){context.runOnClient(client->receive(fixture.country(),local,progressed));context.waitTicks(4);progressImage=context.takeScreenshot("hoi-mission-overlay-source-progress-"+suffix);var picture=javax.imageio.ImageIO.read(progressImage.toFile());int bright=0;for(int y=0;y<picture.getHeight();y++)for(int x=0;x<picture.getWidth();x++){int color=picture.getRGB(x,y),red=color>>16&255,green=color>>8&255,blue=color&255;if(red>150&&green>150&&blue>110&&blue<green*.95&&Math.abs(red-green)<25)bright++;}if(bright<5)throw new AssertionError("Server progress must render the original bright texture half: "+mode+" bright="+bright);context.runOnClient(client->receive(fixture.country(),local,movement));context.waitTicks(3);}
                    context.runOnClient(client->receive("PRK",fixture.cancelled()));context.waitTicks(2);context.runOnClient(client->{if(MapSceneRenderer.visibleTileCount()==0)throw new AssertionError("Foreign cancellation removed owned source route: "+mode);receive(fixture.country(),fixture.cancelled());});context.waitFor(client->MapSceneRenderer.visibleTileCount()==0);context.waitTicks(3);Path cancelled=context.takeScreenshot("hoi-mission-overlay-source-cancelled-"+suffix);
                    var before=javax.imageio.ImageIO.read(active.toFile());var after=javax.imageio.ImageIO.read(cancelled.toFile());if(before.getWidth()!=size[0]||before.getHeight()!=size[1]||after.getWidth()!=size[0]||after.getHeight()!=size[1])throw new AssertionError("Wrong GUI2 framebuffer size");int green=0,removed=0;for(int y=0;y<before.getHeight();y++)for(int x=0;x<before.getWidth();x++){int a=before.getRGB(x,y),b=after.getRGB(x,y),r=a>>16&255,g=a>>8&255,blue=a&255;if(r>100&&g>90&&r>=g*.95&&blue<g*.8){green++;int difference=Math.abs(r-(b>>16&255))+Math.abs(g-(b>>8&255))+Math.abs(blue-(b&255));if(difference>80)removed++;}}if(green<30||removed<20)throw new AssertionError("Actual source arrow must render and disappear: "+mode+" arrowPixels="+green+" removed="+removed);evidence.add(new Evidence(mode,size[0],size[1],2,hash,local.size()+movement.size(),green,removed,active.toString(),progressImage==null?"":progressImage.toString(),cancelled.toString(),fixture.clearAction()));
                    if(!mode.equals("AIR"))sequence(context,fixture,offsetX,offsetZ,suffix);
                }
                context.runOnClient(client->MapSceneRenderer.clearPlans());command.accept("fill 0 249 0 "+extent+" 249 "+extent+" minecraft:air strict");
            }
            if(evidence.size()!=6)throw new AssertionError("All three source modes require both GUI2 resolutions");Path report=Path.of(evidence.getFirst().activeImage()).getParent().resolve("hoi-mission-overlay-source-evidence.json");Files.writeString(report,new Gson().toJson(evidence));
        }catch(java.io.IOException error){throw new java.io.UncheckedIOException(error);}catch(java.security.NoSuchAlgorithmException error){throw new IllegalStateException(error);}finally{context.runOnClient(client->{MapSceneRenderer.clear();client.options.guiScale().set((Integer)original[0]);if(client.gui.hud.isHidden()!=(Boolean)original[1])client.gui.hud.toggle();ClientCampaignHud.accept((ProtocolHudPayloads.State)original[2]);});context.getInput().resizeWindow(1400,1000);}
    }
    private static void sequence(ClientGameTestContext context,Fixture fixture,double dx,double dz,String suffix) throws java.io.IOException {
        if(fixture.sequence()==null||fixture.sequence().size()!=3)throw new AssertionError("Actual clock-driven movement sequence is required");var evidence=new ArrayList<SequenceEvidence>();context.runOnClient(client->{MapCommanderHud.reset();MapUnitHud.reset();if(client.gui.hud.isHidden())client.gui.hud.toggle();});
        for(int index=0;index<3;index++){
            var step=fixture.sequence().get(index);var c=step.counter();var counter=new ProtocolUnitHud.Counter(c.stack(),c.country(),c.countryName(),c.type(),c.name(),c.count(),c.x()+dx,250,c.z()+dz,c.organization(),c.strength(),c.supply(),c.battalions(),c.capitals(),c.status(),c.allegiance(),c.battalionMaximums());var quads=translate(step.movement(),dx,dz);String stage=List.of("zero","middle","next-province").get(index);
            context.runOnClient(client->{receive(fixture.country(),List.of(),quads);MapUnitHud.accept(new ProtocolUnitHud.Snapshot("minecraft:overworld",List.of(counter)));});context.waitTicks(4);
            var box=context.computeOnClient(client->MapUnitHud.boxes().stream().filter(b->b.counter().stack().equals(counter.stack())).findFirst().orElseThrow(()->new AssertionError("Actual server counter must be visible beside movement arrow")));if(box.counter().x()!=counter.x()||box.counter().z()!=counter.z())throw new AssertionError("Renderer altered authoritative counter position");
            Path shot=context.takeScreenshot("hoi-movement-counter-"+stage+"-"+suffix);evidence.add(new SequenceEvidence(stage,step.gameMinute(),step.progress(),step.province(),counter.x(),counter.z(),box.x(),box.y(),shot.toString()));
        }
        var first=evidence.getFirst();var middle=evidence.get(1);var last=evidence.getLast();if(first.gameMinute()>=middle.gameMinute()||middle.gameMinute()>=last.gameMinute()||first.screenX()!=middle.screenX()||first.screenY()!=middle.screenY()||first.screenX()==last.screenX()&&first.screenY()==last.screenY())throw new AssertionError("The same timed sequence must keep the counter fixed, then jump to next province");Files.writeString(Path.of(first.image()).getParent().resolve("hoi-movement-counter-sequence-"+suffix+".json"),new Gson().toJson(evidence));context.runOnClient(client->{MapUnitHud.reset();MapSceneRenderer.clearPlans();if(!client.gui.hud.isHidden())client.gui.hud.toggle();});
    }
    private static List<ProtocolCommanderHud.MovementQuad> translate(List<ProtocolCommanderHud.MovementQuad> source,double x,double z){return source.stream().map(q->new ProtocolCommanderHud.MovementQuad((float)(q.x()+x),q.y()+186,(float)(q.z()+z),q.width(),q.length(),q.yaw(),q.u0(),q.v0(),q.u1(),q.v1())).toList();}
    private static void receive(String country,List<ProtocolAtlasScene.Box> boxes){receive(country,boxes,List.of());}
    private static void receive(String country,List<ProtocolAtlasScene.Box> boxes,List<ProtocolCommanderHud.MovementQuad> quads){int size=ProtocolAtlasScene.PAGE_SIZE,count=Math.max(1,(Math.max(boxes.size(),quads.size())+size-1)/size);UUID scene=UUID.randomUUID();for(int i=0;i<count;i++){int start=i*size;MapSceneRenderer.receivePlans(country,new ProtocolAtlasScene.Page(scene,"minecraft:overworld",i,count,boxes.subList(Math.min(start,boxes.size()),Math.min(start+size,boxes.size()))),quads.subList(Math.min(start,quads.size()),Math.min(start+size,quads.size())));}}
}
